#' @param pictoSize .
#' @param pictoGrid .
#' @param showParliament .
#' @param parlSeats .
#' @param parlRows .
#' @param parlSize .
#' @param parlGrid .
#' @param showProfile .
#' @param profLines .
#' @param profPoints .
#' @param profLabels .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$hint} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plot_bars} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_diverging} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_heat} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_waffle} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_picto} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_parliament} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_profile} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' @export
distOrd <- function(
    data,
    vars,
    orientation = "horizontal",
    useDesc = FALSE,
    invertVars = FALSE,
    colourPalette = "jamovi",
    reversePalette = FALSE,
    plotTheme = "jamovi",
    textSize = 16,
    sortVars = "none",
    decimals = 0,
    legendPos = "bottom",
    legendTitle = "",
    title = "",
    alpha = 80,
    lineWidth = 2,
    ignoreMissing = TRUE,
    showN = FALSE,
    showBars = TRUE,
    barWidth = 70,
    barLabels = TRUE,
    barMinLabel = 5,
    showDiverging = FALSE,
    divWidth = 70,
    divNeutral = "auto",
    divLabels = TRUE,
    divMinLabel = 8,
    divNet = FALSE,
    showHeat = FALSE,
    heatPalette = "blues",
    heatLabels = TRUE,
    heatGap = 4,
    showWaffle = FALSE,
    waffleRows = 10,
    waffleCols = 10,
    waffleGap = 10,
    waffleGrid = 3,
    showPicto = FALSE,
    pictoRows = 10,
    pictoCols = 10,
    pictoShape = "circle",
    pictoSize = 4.5,
    pictoGrid = 3,
    showParliament = FALSE,
    parlSeats = 100,
    parlRows = 4,
    parlSize = 3.2,
    parlGrid = 3,
    showProfile = FALSE,
    profLines = TRUE,
    profPoints = TRUE,
    profLabels = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("distOrd requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))

    for (v in vars) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- distOrdOptions$new(
        vars = vars,
        orientation = orientation,
        useDesc = useDesc,
        invertVars = invertVars,
        colourPalette = colourPalette,
        reversePalette = reversePalette,
        plotTheme = plotTheme,
        textSize = textSize,
        sortVars = sortVars,
        decimals = decimals,
        legendPos = legendPos,
        legendTitle = legendTitle,
        title = title,
        alpha = alpha,
        lineWidth = lineWidth,
        ignoreMissing = ignoreMissing,
        showN = showN,
        showBars = showBars,
        barWidth = barWidth,
        barLabels = barLabels,
        barMinLabel = barMinLabel,
        showDiverging = showDiverging,
        divWidth = divWidth,
        divNeutral = divNeutral,
        divLabels = divLabels,
        divMinLabel = divMinLabel,
        divNet = divNet,
        showHeat = showHeat,
        heatPalette = heatPalette,
        heatLabels = heatLabels,
        heatGap = heatGap,
        showWaffle = showWaffle,
        waffleRows = waffleRows,
        waffleCols = waffleCols,
        waffleGap = waffleGap,
        waffleGrid = waffleGrid,
        showPicto = showPicto,
        pictoRows = pictoRows,
        pictoCols = pictoCols,
        pictoShape = pictoShape,
        pictoSize = pictoSize,
        pictoGrid = pictoGrid,
        showParliament = showParliament,
        parlSeats = parlSeats,
        parlRows = parlRows,
        parlSize = parlSize,
        parlGrid = parlGrid,
        showProfile = showProfile,
        profLines = profLines,
        profPoints = profPoints,
        profLabels = profLabels)

    analysis <- distOrdClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

